            Describe.Lean(DescribeId.Create("positivej-eq-candidatej-complex"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/ComplexRadial/Applications.positiveJ_eq_candidateJ_complex"), H("positiveJ_eq_candidateJ_complex"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The positive J kernel equals the signed positive J formula on the original complex source domain."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("signedj-eq-candidatej-complex"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/ComplexRadial/Applications.signedJ_eq_candidateJ_complex"), H("signedJ_eq_candidateJ_complex"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Every J sector with a negative label equals its signed candidate on the original complex source domain."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("allsignsj-eq-candidatej-complex"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/ComplexRadial/Applications.allSignsJ_eq_candidateJ_complex"), H("allSignsJ_eq_candidateJ_complex"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("All four J sign sectors satisfy the exact complex radial identification."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("signedt-eq-candidatet-complex"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/ComplexRadial/Applications.signedT_eq_candidateT_complex"), H("signedT_eq_candidateT_complex"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Every T sector with a negative label equals its signed candidate on the original complex source domain."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("positivet-eq-candidatet-complex"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/ComplexRadial/Applications.positiveT_eq_candidateT_complex"), H("positiveT_eq_candidateT_complex"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The positive T kernel equals the signed positive T formula, consuming the actual positive T generator theorem and the exact candidate denominator identification."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("allsignst-eq-candidatet-complex"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/ComplexRadial/Applications.allSignsT_eq_candidateT_complex"), H("allSignsT_eq_candidateT_complex"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("All four T sign sectors satisfy the exact complex radial identification."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("allsignsjt-eq-candidates-complex"), DeclarationHandle.Create("D5/S3/VertexAlgebra/TwistedGround/ComplexRadial/Applications.allSignsJT_eq_candidates_complex"), H("allSignsJT_eq_candidates_complex"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For all e,f:Bool and u,v,z:Complex, the only hypotheses are norm(u)+norm(z)<1 and norm(v)+norm(z)<1. Both literal original kernelMode(false,e,f,u,v,z)=candidateJ(e,f,u,v,z^2) and kernelMode(true,e,f,u,v,z)=candidateT(e,f,u,v,z^2) hold. No regularity, equality, nonzero or PDE premise is added."))), DescribeRole.Theorem))));
